DO $$ DECLARE f text; sig text; BEGIN FOREACH sig IN ARRAY ARRAY['public.open_vehicle_chat(uuid)','public.open_vehicle_demand_chat(uuid)','public.open_anonymous_bell_chat(uuid,text)'] LOOP f:=pg_get_functiondef(sig::regprocedure); IF sig LIKE '%open_anonymous%' THEN f:=replace(f,'IF NOT public.profile_ready_for_actions(auth.uid()) THEN RAISE EXCEPTION ''PROFILE_REQUIRED''; END IF;', 'IF _source NOT IN (''vehicle'',''post'') AND NOT public.profile_ready_for_actions(auth.uid()) THEN RAISE EXCEPTION ''PROFILE_REQUIRED''; END IF;'); ELSE f:=replace(f,'IF NOT public.profile_ready_for_actions(auth.uid()) THEN RAISE EXCEPTION ''PROFILE_REQUIRED''; END IF;', ''); END IF; EXECUTE f; END LOOP; END $$;